#include <stdio.h>
#include <stdarg.h>

double average_values(int count, ...)
{
    if (count <= 0) {
        return 0.0;
    }
    va_list arguments;
    va_start(arguments, count);
    double total = 0.0;
    for (int i = 0; i < count; i++) {
        total += va_arg(arguments, double);
    }
    va_end(arguments);
    return total / count;
}

int main(void)
{
    float a = 1.5f;
    printf("%.2f\n", average_values(2, a, 2.5));
    return 0;
}

